WITH parents(NameID, Name) AS (VALUES (1, 'Gavin'), (2, 'Liz'), (3, 'Mr Nobody'), (4, 'Anywhere')), children(NameID, Addr, ChildOrder) AS (VALUES (1, '10 Malt Lane', 1), (2, '10 Malt Lane', 2), (2, '3 The cottages', 3), (4, 'Here', 4), (4, 'There', 5), (4, 'Near', 6), (4, 'Far', 7))
SELECT NameID, Name, 0 AS NumRows, CAST([] AS STRUCT(NameID INTEGER, Addr VARCHAR)[]) AS Children FROM parents ORDER BY NameID;
WITH parents(NameID, Name) AS (VALUES (1, 'Gavin'), (2, 'Liz'), (3, 'Mr Nobody'), (4, 'Anywhere')), children(NameID, Addr, ChildOrder) AS (VALUES (1, '10 Malt Lane', 1), (2, '10 Malt Lane', 2), (2, '3 The cottages', 3), (4, 'Here', 4), (4, 'There', 5), (4, 'Near', 6), (4, 'Far', 7))
SELECT p.NameID, p.Name, CAST(COUNT(c.ChildOrder) AS TINYINT) AS NumRows, COALESCE(LIST(STRUCT_PACK(NameID := c.NameID, Addr := c.Addr) ORDER BY c.ChildOrder) FILTER (WHERE c.ChildOrder IS NOT NULL), CAST([] AS STRUCT(NameID INTEGER, Addr VARCHAR)[])) AS Children FROM parents p LEFT JOIN children c USING (NameID) GROUP BY p.NameID, p.Name ORDER BY p.NameID;
WITH parents(NameID, Name) AS (VALUES (1, 'Gavin'), (2, 'Liz'), (3, 'Mr Nobody'), (4, 'Anywhere'))
SELECT NameID, Name FROM parents ORDER BY NameID;
WITH children(NameID, Addr, ChildOrder) AS (VALUES (1, '10 Malt Lane', 1), (2, '10 Malt Lane', 2), (2, '3 The cottages', 3), (4, 'Here', 4), (4, 'There', 5), (4, 'Near', 6), (4, 'Far', 7))
SELECT NameID, Addr FROM children ORDER BY ChildOrder;

